<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_role(['Admin','Property Officer']);
$type=in_array($_GET['type']??'', ['NOC','Surrender'], true) ? $_GET['type'] : 'NOC';
if($_SERVER['REQUEST_METHOD']==='POST'){ $decision=in_array($_POST['decision']??'', ['Approved','Rejected'], true)?$_POST['decision']:''; $id=(int)($_POST['request_id']??0); if($decision&&$id){$s=$pdo->prepare("UPDATE citizen_requests SET status=? WHERE id=? AND request_type=?");$s->execute([$decision,$id,$type]); if($type==='Surrender'&&$decision==='Approved'){$p=$pdo->prepare('DELETE FROM allottees WHERE property_id=(SELECT property_id FROM citizen_requests WHERE id=?)');$p->execute([$id]);}} header('Location: permission_requests.php?type='.$type); exit;}
$s=$pdo->prepare("SELECT r.*,p.property_code,p.scheme_name,c.phone_number FROM citizen_requests r JOIN properties p ON p.id=r.property_id JOIN citizens c ON c.id=r.citizen_id WHERE r.request_type=? ORDER BY r.created_at DESC");$s->execute([$type]);$requests=$s->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $type ?> Process</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">📝 <?= $type ?> Process</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title"><?= $type ?> Applications</h1><p class="portal-page-subtitle">Citizen applications ko approve ya reject karein.</p></div><div class="mb-3"><a class="btn btn-sm <?= $type==='NOC'?'btn-primary':'btn-outline-primary' ?>" href="?type=NOC">NOC</a> <a class="btn btn-sm <?= $type==='Surrender'?'btn-primary':'btn-outline-primary' ?>" href="?type=Surrender">Surrender</a></div><div class="dashboard-shell table-responsive"><table class="table align-middle"><thead><tr><th>S.No.</th><th>Reference</th><th>Property</th><th>Citizen</th><th>Details</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><?= htmlspecialchars($r['reference_number']) ?></td><td><?= htmlspecialchars($r['property_code'].' - '.$r['scheme_name']) ?></td><td><?= htmlspecialchars($r['phone_number']) ?></td><td><?= htmlspecialchars($r['details']?:'-') ?></td><td><?= htmlspecialchars($r['status']) ?></td><td><?php if(in_array($r['status'],['Submitted','Under Review'],true)): ?><form method="post" class="d-flex gap-1"><input type="hidden" name="request_id" value="<?= $r['id'] ?>"><button name="decision" value="Approved" class="btn btn-sm btn-success">Approve</button><button name="decision" value="Rejected" class="btn btn-sm btn-danger">Reject</button></form><?php else: ?>Done<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$requests): ?><tr><td colspan="7" class="text-center text-muted">No applications found.</td></tr><?php endif; ?></tbody></table></div></main></div></body></html>
